static void costs(const std::filesystem::path& path){std::ofstream f(path);for(int c=0;c<=14;++c)for(int a=0;a<=1;++a)for(int rp=0;rp<=1;++rp){const std::int64_t ol=a?(c-1)*(c-1):0,om=a?0:(c-2)*(c-2);for(int delta:std::array<int,2>{-1,1})if(c+delta>=0&&c+delta<=14){const int nc=c+delta;const std::int64_t nl=a?(nc-1)*(nc-1):0,nm=a?0:(nc-2)*(nc-2);f<<"{\"kind\":\"CN\",\"c\":"<<c<<",\"a\":"<<a<<",\"root_pair\":"<<rp<<",\"delta\":"<<delta<<",\"delta_lambda\":"<<nl-ol<<",\"delta_mu\":"<<nm-om<<",\"delta_root\":"<<(rp?nm-om:0)<<",\"delta_F\":"<<WEIGHT*(nl-ol)+(rp?nm-om:0)<<"}\n";}const int na=1-a;const std::int64_t nl=na?(c-1)*(c-1):0,nm=na?0:(c-2)*(c-2);f<<"{\"kind\":\"EDGE\",\"c\":"<<c<<",\"a\":"<<a<<",\"root_pair\":"<<rp<<",\"delta\":"<<na-a<<",\"delta_lambda\":"<<nl-ol<<",\"delta_mu\":"<<nm-om<<",\"delta_root\":"<<(rp?nm-om:0)<<",\"delta_F\":"<<WEIGHT*(nl-ol)+(rp?nm-om:0)<<"}\n";}f.flush();need(static_cast<bool>(f),"complete pair costs");}
static Options parse(int argc,char** argv){Options o;for(int i=1;i<argc;++i){std::string k=argv[i];if(k=="--forced"){o.forced=true;continue;}if(k=="--stop-at-localzero"){o.stop_zero=true;continue;}if(k=="--emit-pair-costs"){o.pair_costs=true;continue;}need(i+1<argc,"argument value");std::string v=argv[++i];if(k=="--out")o.out=v;else if(k=="--fixture")o.fixture=v;else if(k=="--resume")o.resume=v;else if(k=="--graph-input")o.graph_input=v;else if(k=="--frozen-reference")o.frozen_reference=v;else if(k=="--graph-identity")o.graph_identity=v;else if(k=="--probe-file")o.probe_file=v;else if(k=="--probe-identity")o.probe_identity=v;else if(k=="--root")o.root=static_cast<int>(uint_text(v));else if(k=="--seed")o.seed=uint_text(v);else if(k=="--steps")o.steps=uint_text(v);else if(k=="--mix-steps")o.mix=uint_text(v);else if(k=="--schedule-steps")o.schedule=uint_text(v);else if(k=="--verify-every")o.verify_every=uint_text(v);else if(k=="--checkpoint-every")o.checkpoint_every=uint_text(v);else if(k=="--trace-max")o.trace_max=uint_text(v);else if(k=="--trace-stride")o.trace_stride=uint_text(v);else if(k=="--temperature-start")o.start=std::stod(v);else if(k=="--temperature-end")o.end=std::stod(v);else if(k=="--seconds")o.seconds=std::stod(v);else need(false,"unknown argument "+k);}need(!o.out.empty()&&o.seconds>0&&o.seconds<=21600&&std::isfinite(o.seconds),"out/time arguments");need(o.root>=0&&o.root<MAX_N&&o.verify_every>0&&o.checkpoint_every>0&&o.schedule>0,"root and intervals");need(std::isfinite(o.start)&&std::isfinite(o.end)&&o.start>=0&&o.end>=0&&o.start<=1000&&o.end<=1000,"bounded temperatures");need(o.resume.empty()||o.graph_input.empty(),"resume/import exclusive");need(hash_text(o.graph_identity)&&hash_text(o.probe_identity),"argument hash syntax");need(o.probe_file.empty()==(o.probe_identity==std::string(64,'0')),"probe file identity presence");return o;}

